<template>
  <div>
    <el-button
      type="primary"
      plain
      icon="el-icon-plus"
      size="mini"
      @click="addData"
      >新增</el-button
    >
    <el-table
      :data="dataList"
      style="width: 100%"
      class="mt-10"
      v-loading="loading"
      size="small"
    >
      <el-table-column type="index" label="序号" align="center" />
      <el-table-column prop="source_name" label="数据源名称" align="center" />
      <el-table-column prop="describe" label="属性名称" align="center" />
      <el-table-column prop="category" label="分析类型" align="center">
        <template slot-scope="scope">
          {{ categoryList.get(scope.row.category) }}
        </template>
      </el-table-column>

      <el-table-column label="操作" align="center">
        <template slot-scope="scope">
          <el-button
            type="text"
            @click="editData(scope.row)"
            class="el-icon-edit"
          ></el-button>
          <el-button
            type="text"
            @click="delData(scope.row)"
            class="el-icon-delete"
            style="color: red"
          ></el-button>
        </template>
      </el-table-column>
    </el-table>
    <pagination
      class="float-right mb-10"
      v-show="total > 0"
      :total="total"
      :page.sync="queryForm.page"
      :limit.sync="queryForm.size"
      @pagination="getData"
      layout="total, prev, pager, next"
      small
    />
    <el-dialog
      :title="title"
      :visible.sync="addVisible"
      width="40%"
      :close-on-click-modal="false"
      top="10px"
    >
      <el-form
        :model="addForm"
        ref="addForm"
        label-width="120px"
        class="mt-20"
        size="small"
      >
        <el-form-item label="数据源:" prop="source_id">
          <el-select v-model="addForm.source_id" @change="changeSource">
            <el-option
              :value="item.id"
              :label="item.source_name"
              v-for="item in sourceList"
              :key="item.id"
            ></el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="属性:" prop="pro_id">
          <el-select v-model="addForm.pro_id">
            <el-option
              :value="item.id"
              :label="item.describe"
              v-for="item in proList"
              :key="item.id"
            ></el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="分析类型:" prop="category">
          <el-select v-model="addForm.category">
            <el-option
              :value="value"
              :label="label"
              v-for="[value, label] in categoryList"
              :key="value"
            ></el-option>
          </el-select>
        </el-form-item>
      </el-form>
      <span slot="footer" class="dialog-footer">
        <el-button @click="addVisible = false">取 消</el-button>
        <el-button type="primary" @click="submitForm('addForm')"
          >确 定</el-button
        >
      </span>
    </el-dialog>
  </div>
</template>

<script>
export default {
  data() {
    return {
      dataList: [],
      loading: false,
      fileList: [],
      addForm: {},
      addVisible: false,
      title: "",
      queryForm: {
        page: 1,
        size: 10,
      },
      total: 0,
      sourceList: [],
      proList: [],
      categoryList: new Map([
        [1, "马歇尔稳定度试验"],
        [2, "延度试验"],
        [3, "针入度试验"],
        [4, "软化点试验"],
        [5, "路面强度试验"],
        [6, "击实试验"],
      ]),
    };
  },
  created() {
    this.getData();
    this.getSourceList();
  },
  methods: {
    changeSource(e) {
      this.$api
        .get("/collect/getDataPropertyList", { params: { source_id: e } })
        .then((res) => {
          this.proList = res.data.data;
        });
    },
    getSourceList() {
      this.$api.get("/collect/getDataSourceList").then((res) => {
        this.sourceList = res.data.data.filter(
          (item) => item.driver_protocol == 1,
        );
      });
    },
    getData() {
      this.$api
        .get("/ai/getVideoAnalysisList", {
          params: this.queryForm,
        })
        .then((res) => {
          if (res.data.data) {
            this.dataList = res.data.data;
            this.total = res.data.total;
          } else {
            this.total = 0;
            this.dataList = [];
          }
        });
    },
    addData() {
      this.addForm = {};
      this.fileList = [];
      this.title = "新增";
      this.addVisible = true;
    },
    editData(row) {
      this.title = "编辑";
      this.addVisible = true;
      this.addForm = { ...row };
      this.changeSource(this.addForm.source_id);
    },
    delData(row) {
      this.$confirm("是否删除该数据?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(() => {
          this.$api
            .post("/ai/delDataVideoAnalysise", { id: row.id })
            .then(() => {
              this.$message.success("操作成功");
              this.getData();
            });
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },
    submitForm() {
      const isEditMode = !!this.addForm.id;
      const apiUrl = isEditMode
        ? "/ai/updateVideoAnalysis"
        : "/ai/addVideoAnalysis";
      this.$api.post(apiUrl, this.addForm).then(() => {
        this.addVisible = false;
        this.$message.success("操作成功");
        this.getData();
      });
    },
  },
};
</script>

<style></style>
